INSERT INTO public.curr_indicadores (grado, asignatura, competencia, codigo, descripcion) VALUES
-- BC1
('2do', 'Lengua Española', 'BC1', 'IL-1', 'Expresa sus ideas a través de textos orales y/o escritos, creando un ambiente cultural e interactivo, desde una perspectiva social.'),
('2do', 'Lengua Española', 'BC1', 'IL-2', 'Emplea la lengua haciendo uso de las diferentes funciones textuales, a través de su expresión personal, creando estructuras para forjar el conocimiento en medios diversos.'),
('2do', 'Lengua Española', 'BC1', 'IL-3', 'Valora los recursos de la lengua y los utiliza al responder preguntas inferenciales y críticas en la comprensión de sentidos.'),

-- BC2
('2do', 'Lengua Española', 'BC2', 'IL-4', 'Demuestra capacidad en el uso de secuencias argumentativas, en la construcción de discursos con temas de su realidad, así como del contexto local, nacional y mundial.'),
('2do', 'Lengua Española', 'BC2', 'IL-5', 'Reconstruye conocimientos sobre situaciones sociales a partir de inferencias en la comprensión y producción de textos funcionales y literarios.'),
('2do', 'Lengua Española', 'BC2', 'IL-6', 'Expone informaciones con juicios y puntos de vista pertinentes, en la construcción de pensamiento estructurado que derivan en conclusiones lógicas, acciones y respeto de opiniones.'),
('2do', 'Lengua Española', 'BC2', 'IL-7', 'Identifica problemas o conflictos del centro educativo y comunitario, a través de un tipo de texto específico y apropiado.'),
('2do', 'Lengua Española', 'BC2', 'IL-8', 'Utiliza textos específicos variados que apoyan la solución de problemas, facilitando la investigación, búsqueda de información, con criterios de relevancia, pertinencia, validez y confiabilidad.'),
('2do', 'Lengua Española', 'BC2', 'IL-9', 'Presenta informes de investigación que evidencian la solución de problemas en un contexto determinado.'),

-- BC3
('2do', 'Lengua Española', 'BC3', 'IL-13', 'Expone conocimientos sobre procesos de investigación en el campo de la ciencia, mediante textos variados y haciendo uso de medios y herramientas tecnológicas.'),
('2do', 'Lengua Española', 'BC3', 'IL-14', 'Analiza textos de secuencia expositivo-explicativa relacionados con investigaciones científicas sencillas, para la comprensión de problemas o situaciones de su entorno familiar, escolar y comunitario.'),
('2do', 'Lengua Española', 'BC3', 'IL-15', 'Redacta textos expositivo-explicativos sobre hallazgos científicos y sociales, haciendo uso de las convenciones de lengua y su divulgación en diferentes contextos.'),
('2do', 'Lengua Española', 'BC3', 'IL-16', 'Caracteriza problemáticas relacionadas con salud y ambiente que afectan el quehacer social, haciendo uso de textos diversos y apoyándose en recursos y medios variados.'),
('2do', 'Lengua Española', 'BC3', 'IL-17', 'Escribe textos sobre la flora y la fauna dominicanas, la salud y el ambiente, identificando especies endémicas, preparación de alimentos sanos, problemas ambientales de actualidad, proceso de reciclaje, zonas protegidas, para una mejor salud integral y ambiente favorable al desarrollo humano.'),
('2do', 'Lengua Española', 'BC3', 'IL-18', 'Aplica conocimientos sobre la conservación de la salud, la naturaleza y sus ecosistemas, redactando textos variados, para su divulgación en actividades de intercomunicación dentro y fuera del aula.'),

-- BC4
('2do', 'Lengua Española', 'BC4', 'IL-10', 'Presenta nuevas relaciones sociales en reconocimiento y valoración de lo natural y sociocultural, haciendo uso de textos, tales como análisis, comentarios, argumentos, entre otros.'),
('2do', 'Lengua Española', 'BC4', 'IL-11', 'Conoce y cuestiona las prácticas sociales de ciudadanía en el entorno local y su confrontación con los valores universales, a través de textos y secuencia argumentativa.'),
('2do', 'Lengua Española', 'BC4', 'IL-12', 'Elabora proyectos colaborativos, utilizando textos variados y apropiados, para la construcción de una ciudadanía que busca soluciones a problemas.'),
('2do', 'Lengua Española', 'BC4', 'IL-19', 'Utiliza un género textual para la comprensión de sí mismo y de los demás en variadas situaciones de comunicación.'),
('2do', 'Lengua Española', 'BC4', 'IL-20', 'Escribe textos literarios para el cultivo de valores universales y reforzar la dimensión humanista y el desarrollo físico y espiritual.'),
('2do', 'Lengua Española', 'BC4', 'IL-21', 'Canalizar emociones y sentimientos mediante lecturas y escrituras reflexivas, fortaleciendo las relaciones humanas, el respeto y la dignidad de las personas.');
